#pragma once
#include <JuceHeader.h>

inline juce::String triceratopsUi(const juce::String& text, bool chinese)
{
    if (text.isEmpty())
        return text;
    static const auto dictionary = juce::JSON::parse(juce::String::fromUTF8(R"ui({"No MIDI notes saved. Check host MIDI routing, the recording point and capture-folder permissions.": "未保存 MIDI 音符，请检查宿主 MIDI 路由、录制点及录制目录权限。", "Send": "发送", "Stop": "停止", "Clear Chat": "清空对话", "Auto-Import: ON": "自动导入：开", "Auto-Import: OFF": "自动导入：关", "Import to REAPER": "导入 REAPER", "Plan / History": "编排 / 历史", "New score": "创作乐段", "Edit MIDI": "编辑 MIDI", "Analyze": "分析", "Continue 4 bars": "续写四小节", "More energy": "增强能量", "Tighten timing": "收紧节奏", "Undo": "上一版本", "Keep": "保留", "Reject": "不喜欢", "Stem split": "音频分轨", "Audio -> MIDI": "音频转 MIDI", "Load MIDI": "载入 MIDI", "Load audio": "载入音频", "Load Audio": "载入音频", "Play VST": "播放 MIDI", "Drag MIDI": "拖出 MIDI", "Rec MIDI": "录制 MIDI", "Rec audio": "录制音频", "Save MIDI": "保存 MIDI", "Save audio": "保存音频", "Capture MIDI": "录制 MIDI", "Capture audio": "录制音频", "SCORE STAVE VISUALIZER": "音符预览", "No musical score generated yet.": "载入或生成 MIDI 后将在这里显示音符。", "Thinking...": "处理中…", "Say anything: sad piano, continue this, more energy, analyze it...": "说说你的想法：温柔一点的钢琴、接着写下去、收紧节奏…", "Score Arrangement Plan will appear here.": "编排计划将在这里显示。", "Version history in this project session will appear here.": "本工程的 MIDI 版本历史将在这里显示。", "CONNECTING TO AGENT": "正在连接 Agent", "Local GPU Model Service": "本地音乐模型服务", "MIDI: None": "MIDI：未载入", "AUDIO: None": "音频：未载入", "Create music: ": "我想创作：", "Change this MIDI: ": "帮我修改这段 MIDI：", "Analyze what I loaded and explain the most useful musical details.": "分析我载入的素材，说明对继续创作有用的音乐细节。", "Continue the loaded MIDI for four bars, keeping its musical identity.": "接着载入的 MIDI 续写四小节，保留它原来的音乐气质。", "Make the loaded MIDI more energetic while keeping the main melody.": "让这段 MIDI 更有能量，保留主旋律。", "Tighten the timing of the loaded MIDI without changing its notes.": "收紧这段 MIDI 的节奏，不改变音高。", "Undo the last MIDI change.": "恢复上一个 MIDI 版本。", "Keep this version. I like it.": "保留这个版本，我喜欢。", "Reject this version and remember that I do not like it.": "这个版本不喜欢，请记住这次反馈。", "Split the loaded audio into stems.": "将载入的音频分离成独立声部。", "Convert the loaded audio to MIDI.": "把载入的音频转成 MIDI。", "Generate a four-bar continuation from the loaded MIDI": "从载入的 MIDI 生成新的四小节", "Increase musical energy while preserving the melody": "保留旋律并增强力度", "Quantize the loaded MIDI to a tighter grid": "将 MIDI 对齐到十六分音符网格", "Accept this result and remember the preference": "保留结果，并记住你的偏好", "Reject this result and remember the feedback": "记录不喜欢此版本的反馈", "LOCAL AI AGENT": "本地音乐 AGENT", "Understanding request & observing DAW project context...": "正在理解要求并读取工程上下文…", "BACKEND OFFLINE": "后端未连接", "Backend connection failed. Check the local service and retry.": "后端连接失败。请运行开始菜单中的 Triceratops 配置程序，完成环境配置后重试。", "WARMING UP MODEL": "正在加载模型", "WARMUP ERROR": "模型加载失败", "Local GPU model service failed to initialize.": "本地模型服务初始化失败。", "AGENT READY": "AGENT 已就绪", "GENERATING...": "正在执行…", "Warming local GPU notation model...": "正在加载本地音乐模型…", "[Observe & Plan] ": "[观察与规划] ", "[GPU Model Sampling] ": "[模型生成] ", "[Constraint Verification] ": "[约束检查] ", "[Processing] ": "[执行中] ", "Operation failed:\n": "操作失败：\n", "USER [": "你 [", "TRICERATOPS AGENT [": "TRICERATOPS [", "Reasoning & Execution Trace:\n": "工具执行记录：\n", "[MIDI Result: ": "[MIDI 结果：", "TRICERATOPS AGENT [THINKING & GENERATING...]\n": "TRICERATOPS [正在处理…]\n", "Live Reasoning Stream:\n": "当前执行进度：\n", "  \\_ [Observe & Plan] Formulating music arrangement strategy...\n": "  \\_ [观察与规划] 正在整理创作要求…\n", "Chat history cleared. Active session reset.": "对话已清空，当前会话已重置。", "Stop requested. Waiting for the active tool to finish cancelling.": "已请求停止，正在等待当前工具结束。", "Load or generate MIDI or stems before importing.": "请先载入或生成 MIDI，或完成音频分轨。", "Importing ": "正在导入 ", " into REAPER track...": " 到 REAPER 轨道…", "Importing separated audio stems into REAPER tracks...": "正在将分轨音频导入 REAPER 轨道…", "\n(Tip: You can also click and drag 'Drag MIDI' directly onto any track in REAPER!)": "\n提示：也可以从“拖出 MIDI”按钮直接拖到 REAPER 轨道。", "Welcome to Triceratops Music Agent!\nOpening plugin session. Models load when their tools are requested.": "欢迎使用 Triceratops 音乐 Agent！\n模型会在需要时加载。说说你想做什么，或点击上方的功能按钮。", "Service ready": "服务已就绪", "Understanding your request...": "正在理解你的要求…", "Observing project context and planning the score": "正在读取工程上下文并整理要求", "MIDI: ": "MIDI：", "AUDIO: ": "音频：", "AI Model Warmup / Caching... Please wait (Model Caching... Generation Paused)": "模型加载中，请稍候…", "AI Model Warmup / Caching... Please wait (GPU Caching... ": "正在加载模型（已等待 ", "s elapsed)": " 秒）", "MODEL WARMUP ERROR EXCEPTION DETAILS:\n----------------------------------------\n": "模型加载错误详情：\n----------------------------------------\n", "ERROR EXCEPTION DETAILS:\n----------------------------------------\n": "错误详情：\n----------------------------------------\n", "Show output file": "显示结果文件", "Drag / import into host": "拖入或导入宿主", "Record audio with Triceratops Audio in an Audio FX slot.": "请在音频效果插槽使用 Triceratops Audio 录制音频。", "Use Triceratops MIDI in a MIDI FX slot before an instrument.": "请在音源之前的 MIDI FX 插槽使用 Triceratops MIDI。", "Drag this button into a MIDI track to import the current file.": "将此按钮拖到 MIDI 轨道以导入当前文件。", "MIDI file drag started: ": "已开始拖出 MIDI 文件：", "Could not start MIDI file drag.": "无法开始拖出 MIDI 文件。"})ui"));
    if (auto* strings = dictionary.getDynamicObject())
    {
        if (chinese && strings->hasProperty(juce::Identifier(text)))
            return strings->getProperty(juce::Identifier(text)).toString();
        if (!chinese)
            for (const auto& item : strings->getProperties())
                if (item.value.toString() == text)
                    return item.name.toString();
    }
    const auto englishPrefix = juce::String("AUDIO: ");
    const auto chinesePrefix = juce::String::fromUTF8("音频：");
    if (chinese && text.startsWith(englishPrefix))
        return chinesePrefix + text.substring(englishPrefix.length());
    if (!chinese && text.startsWith(chinesePrefix))
        return englishPrefix + text.substring(chinesePrefix.length());
    return text;
}
